<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Adjustable Photovoltaic Module</title>
  <style>
    :root {
      color-scheme: light;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #dce5e5;
    }

    #scene {
      position: fixed;
      inset: 0;
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    #scene:active {
      cursor: grabbing;
    }

    .panel {
      position: fixed;
      z-index: 10;
      top: 20px;
      left: 20px;
      width: min(340px, calc(100vw - 40px));
      padding: 20px;
      border: 1px solid rgba(255, 255, 255, 0.72);
      border-radius: 18px;
      background: rgba(248, 251, 251, 0.86);
      box-shadow: 0 18px 50px rgba(30, 50, 55, 0.18);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
    }

    .eyebrow {
      margin-bottom: 7px;
      color: #60747a;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      color: #173039;
      font-size: 22px;
      font-weight: 750;
      line-height: 1.15;
    }

    .subtitle {
      margin: 8px 0 18px;
      color: #60747a;
      font-size: 13px;
      line-height: 1.45;
    }

    .readout {
      display: flex;
      gap: 18px;
      align-items: center;
      padding: 10px 12px;
      border-radius: 10px;
      background: #e7efee;
      color: #425a61;
      font-size: 12px;
      font-weight: 650;
    }

    .readout span {
      white-space: nowrap;
    }

    .readout strong {
      font-size: 14px;
    }

    .control {
      margin-top: 15px;
    }

    .control label {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 8px;
      color: #486068;
      font-size: 12px;
      font-weight: 700;
    }

    .control output {
      min-width: 58px;
      color: #173039;
      text-align: right;
      font-variant-numeric: tabular-nums;
    }

    input[type="range"] {
      width: 100%;
      height: 5px;
      margin: 0;
      border-radius: 999px;
      outline: none;
      appearance: none;
      -webkit-appearance: none;
      background: linear-gradient(
        90deg,
        #789097 0%,
        #789097 var(--fill, 50%),
        #dce4e4 var(--fill, 50%),
        #dce4e4 100%
      );
      cursor: pointer;
    }

    input[type="range"]::-webkit-slider-thumb {
      width: 17px;
      height: 17px;
      border: 3px solid white;
      border-radius: 50%;
      appearance: none;
      -webkit-appearance: none;
      background: #315861;
      box-shadow: 0 2px 7px rgba(25, 50, 55, 0.28);
    }

    input[type="range"]::-moz-range-thumb {
      width: 13px;
      height: 13px;
      border: 3px solid white;
      border-radius: 50%;
      background: #315861;
      box-shadow: 0 2px 7px rgba(25, 50, 55, 0.28);
    }

    .button-row {
      display: flex;
      gap: 9px;
      margin-top: 17px;
    }

    button {
      flex: 1;
      padding: 9px 10px;
      border: 1px solid rgba(53, 85, 94, 0.2);
      border-radius: 9px;
      background: #f4f8f8;
      color: #315861;
      font: inherit;
      font-size: 12px;
      font-weight: 700;
      cursor: pointer;
      transition: background 150ms ease, transform 150ms ease;
    }

    button:hover {
      background: #e8f0f1;
    }

    button:active {
      transform: translateY(1px);
    }

    .hint {
      margin-top: 15px;
      color: #718287;
      font-size: 11px;
      line-height: 1.4;
    }

    #loading {
      position: fixed;
      z-index: 20;
      inset: 0;
      display: grid;
      place-items: center;
      background: #dce5e5;
      color: #526a71;
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      transition: opacity 350ms ease;
    }

    #loading.hidden {
      opacity: 0;
      pointer-events: none;
    }

    @media (max-width: 600px) {
      .panel {
        top: 12px;
        left: 12px;
        width: calc(100vw - 24px);
        padding: 16px;
      }

      h1 {
        font-size: 19px;
      }

      .subtitle {
        margin-bottom: 13px;
      }
    }
  </style>
</head>
<body>
  <canvas id="scene" aria-label="Interactive 3D photovoltaic module"></canvas>

  <section class="panel">
    <div class="eyebrow">Ground-Mounted PV System</div>
    <h1>Adjustable Photovoltaic Module</h1>
    <p class="subtitle">
      A single framed module, supported by two rails, four telescoping struts,
      and a pair of concrete footings.
    </p>

    <div class="readout">
      <span>Tilt<strong id="tiltValue">28°</strong></span>
      <span>Rail height<strong id="heightValue">2.55 m</strong></span>
    </div>

    <div class="control">
      <label for="tilt">
        Module tilt
        <output id="tiltOutput">28°</output>
      </label>
      <input id="tilt" type="range" min="12" max="55" value="28" step="1">
    </div>

    <div class="control">
      <label for="height">
        Rail/support height
        <output id="heightOutput">2.55 m</output>
      </label>
      <input id="height" type="range" min="1.5" max="3.3" value="2.55" step="0.05">
    </div>

    <div class="button-row">
      <button id="reset" type="button">Reset view</button>
      <button id="front" type="button">Front view</button>
    </div>

    <div class="hint">
      Drag to orbit · Wheel or pinch to zoom · Shift-drag or right-drag to pan ·
      Arrow keys rotate · + / − zoom
    </div>
  </section>

  <div id="loading">Loading 3D scene…</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const canvas = document.querySelector("#scene");
    const loading = document.querySelector("#loading");
    const tiltInput = document.querySelector("#tilt");
    const heightInput = document.querySelector("#height");
    const tiltOutput = document.querySelector("#tiltOutput");
    const heightOutput = document.querySelector("#heightOutput");
    const tiltValue = document.querySelector("#tiltValue");
    const heightValue = document.querySelector("#heightValue");

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xdce5e5);
    scene.fog = new THREE.Fog(0xdce5e5, 15, 36);

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    const camera = new THREE.PerspectiveCamera(
      40,
      window.innerWidth / window.innerHeight,
      0.05,
      80
    );

    // Camera controls are implemented directly without external addons.
    const controls = {
      target: new THREE.Vector3(0, 2.55, 0),
      radius: 10.8,
      theta: 0.72,
      phi: 1.08
    };

    const defaultCamera = {
      target: controls.target.clone(),
      radius: controls.radius,
      theta: controls.theta,
      phi: controls.phi
    };

    function updateCamera() {
      const sinPhi = Math.sin(controls.phi);
      camera.position.set(
        controls.target.x + controls.radius * sinPhi * Math.sin(controls.theta),
        controls.target.y + controls.radius * Math.cos(controls.phi),
        controls.target.z + controls.radius * sinPhi * Math.cos(controls.theta)
      );
      camera.lookAt(controls.target);
    }

    updateCamera();

    // Lighting
    const hemisphere = new THREE.HemisphereLight(0xeaf7ff, 0x756b5c, 2.15);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xfff4df, 3.25);
    sun.position.set(-6, 11, 7);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -9;
    sun.shadow.camera.right = 9;
    sun.shadow.camera.top = 9;
    sun.shadow.camera.bottom = -9;
    sun.shadow.camera.near = 0.5;
    sun.shadow.camera.far = 30;
    sun.shadow.normalBias = 0.025;
    sun.shadow.bias = -0.0002;
    scene.add(sun);

    const fill = new THREE.DirectionalLight(0xc9e5f2, 0.75);
    fill.position.set(7, 5, -6);
    scene.add(fill);

    // Procedural materials and textures
    function seededRandom(seed) {
      let value = seed >>> 0;
      return () => {
        value = (value * 1664525 + 1013904223) >>> 0;
        return value / 4294967296;
      };
    }

    function createConcreteTexture() {
      const random = seededRandom(1287);
      const c = document.createElement("canvas");
      c.width = c.height = 256;
      const ctx = c.getContext("2d");

      ctx.fillStyle = "#858781";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 950; i++) {
        const shade = 85 + Math.floor(random() * 90);
        const alpha = 0.025 + random() * 0.08;
        ctx.fillStyle = `rgba(${shade},${shade},${shade - 4},${alpha})`;
        const size = 1 + random() * 5;
        ctx.fillRect(random() * 256, random() * 256, size, size);
      }

      for (let i = 0; i < 35; i++) {
        const x = random() * 256;
        const y = random() * 256;
        const radius = 1 + random() * 3;
        const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
        gradient.addColorStop(0, "rgba(45,48,45,0.12)");
        gradient.addColorStop(1, "rgba(45,48,45,0)");
        ctx.fillStyle = gradient;
        ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
      }

      const texture = new THREE.CanvasTexture(c);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(2, 2);
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    function createPanelTexture() {
      const random = seededRandom(9217);
      const c = document.createElement("canvas");
      c.width = 1024;
      c.height = 640;
      const ctx = c.getContext("2d");

      ctx.fillStyle = "#06152d";
      ctx.fillRect(0, 0, c.width, c.height);

      const columns = 10;
      const rows = 6;
      const cellWidth = c.width / columns;
      const cellHeight = c.height / rows;

      for (let row = 0; row < rows; row++) {
        for (let column = 0; column < columns; column++) {
          const x = column * cellWidth;
          const y = row * cellHeight;
          const gradient = ctx.createLinearGradient(x, y, x + cellWidth, y + cellHeight);
          gradient.addColorStop(0, "#123c69");
          gradient.addColorStop(0.45, "#0a2143");
          gradient.addColorStop(1, "#06152d");
          ctx.fillStyle = gradient;
          ctx.fillRect(x + 2, y + 2, cellWidth - 4, cellHeight - 4);

          ctx.strokeStyle = "rgba(154,205,235,0.19)";
          ctx.lineWidth = 2;
          ctx.strokeRect(x + 3, y + 3, cellWidth - 6, cellHeight - 6);

          ctx.fillStyle = "rgba(184,225,255,0.13)";
          ctx.fillRect(x + 5, y + 5, cellWidth - 10, 2);

          const variation = Math.floor(random() * 18);
          ctx.fillStyle = `rgba(255,255,255,${variation / 255 * 0.035})`;
          ctx.fillRect(x + 7, y + 7, cellWidth - 14, 1);
        }
      }

      // Fine busbars between the photovoltaic cells.
      for (let column = 0; column <= columns; column++) {
        const x = column * cellWidth;
        ctx.fillStyle = "rgba(197,226,247,0.45)";
        ctx.fillRect(x, 0, 2, c.height);
      }

      // Subtle panel glare.
      const glare = ctx.createLinearGradient(0, 0, c.width, 0);
      glare.addColorStop(0, "rgba(255,255,255,0)");
      glare.addColorStop(0.4, "rgba(255,255,255,0.035)");
      glare.addColorStop(0.52, "rgba(255,255,255,0)");
      ctx.fillStyle = glare;
      ctx.fillRect(0, 0, c.width, c.height);

      const texture = new THREE.CanvasTexture(c);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    const materials = {
      steel: new THREE.MeshStandardMaterial({
        color: 0x68777d,
        metalness: 0.82,
        roughness: 0.3
      }),
      darkSteel: new THREE.MeshStandardMaterial({
        color: 0x303d43,
        metalness: 0.76,
        roughness: 0.38
      }),
      brightSteel: new THREE.MeshStandardMaterial({
        color: 0xaeb9bd,
        metalness: 0.9,
        roughness: 0.24
      }),
      black: new THREE.MeshStandardMaterial({
        color: 0x111719,
        metalness: 0.25,
        roughness: 0.55
      }),
      concrete: new THREE.MeshStandardMaterial({
        map: createConcreteTexture(),
        color: 0xb0b1aa,
        roughness: 0.96,
        metalness: 0.02
      }),
      panel: new THREE.MeshStandardMaterial({
        map: createPanelTexture(),
        emissive: 0x06152d,
        emissiveIntensity: 0.24,
        metalness: 0.28,
        roughness: 0.3
      })
    };

    function addBox(parent, size, position, material, castShadow = true) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(size.x, size.y, size.z),
        material
      );
      mesh.position.copy(position);
      mesh.castShadow = castShadow;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function cylinderBetween(parent, a, b, radius, material, radialSegments = 16) {
      const direction = new THREE.Vector3().subVectors(b, a);
      const length = direction.length();
      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        radialSegments
      );
      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.copy(a).add(b).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // Ground and reference grid
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      new THREE.MeshStandardMaterial({
        color: 0xbec8c6,
        roughness: 0.95,
        metalness: 0
      })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.012;
    ground.receiveShadow = true;
    scene.add(ground);

    const grid = new THREE.GridHelper(32, 32, 0x718181, 0x9ba6a4);
    grid.position.y = 0.002;
    grid.material.transparent = true;
    grid.material.opacity = 0.22;
    scene.add(grid);

    // Support frame
    const supportGroup = new THREE.Group();
    scene.add(supportGroup);

    const railHeight = 2.55;
    const moduleCenterHeight = 3.85;
    const moduleGroup = new THREE.Group();
    moduleGroup.position.y = moduleCenterHeight;
    moduleGroup.rotation.x = THREE.MathUtils.degToRad(28);
    scene.add(moduleGroup);

    const railY = railHeight;
    const crossbarY = railHeight - 0.15;

    // Two long structural rails
    for (const z of [-0.8, 0.8]) {
      addBox(
        supportGroup,
        new THREE.Vector3(5.45, 0.17, 0.19),
        new THREE.Vector3(0, railY, z),
        materials.steel
      );
    }

    // Two crossbars joining the rails
    for (const x of [-2.15, 2.15]) {
      addBox(
        supportGroup,
        new THREE.Vector3(0.19, 0.15, 1.86),
        new THREE.Vector3(x, crossbarY, 0),
        materials.steel
      );
    }

    // Mounting plates and bolts at the rail/crossbar intersections
    for (const x of [-2.15, 2.15]) {
      for (const z of [-0.8, 0.8]) {
        addBox(
          supportGroup,
          new THREE.Vector3(0.34, 0.07, 0.3),
          new THREE.Vector3(x, railY - 0.105, z),
          materials.darkSteel
        );

        for (const dx of [-0.1, 0.1]) {
          for (const dz of [-0.1, 0.1]) {
            const bolt = new THREE.Mesh(
              new THREE.CylinderGeometry(0.045, 0.045, 0.05, 6),
              materials.brightSteel
            );
            bolt.position.set(x + dx, railY - 0.055, z + dz);
            bolt.castShadow = true;
            supportGroup.add(bolt);
          }
        }
      }
    }

    // Concrete footings
    function createFooting(x) {
      const footing = new THREE.Group();
      footing.position.x = x;
      scene.add(footing);

      addBox(
        footing,
        new THREE.Vector3(1.38, 0.18, 1.3),
        new THREE.Vector3(0, 0.09, 0),
        materials.concrete
      );

      addBox(
        footing,
        new THREE.Vector3(1.08, 0.44, 1.0),
        new THREE.Vector3(0, 0.38, 0),
        materials.concrete
      );

      addBox(
        footing,
        new THREE.Vector3(0.94, 0.08, 0.86),
        new THREE.Vector3(0, 0.62, 0),
        materials.concrete
      );

      // Four anchor bolts per footing
      for (const dx of [-0.34, 0.34]) {
        for (const dz of [-0.34, 0.34]) {
          const washer = new THREE.Mesh(
            new THREE.CylinderGeometry(0.105, 0.105, 0.025, 24),
            materials.darkSteel
          );
          washer.position.set(dx, 0.68, dz);
          washer.receiveShadow = true;
          footing.add(washer);

          const bolt = new THREE.Mesh(
            new THREE.CylinderGeometry(0.065, 0.075, 0.12, 6),
            materials.brightSteel
          );
          bolt.position.set(dx, 0.75, dz);
          bolt.castShadow = true;
          footing.add(bolt);
        }
      }
    }

    createFooting(-2.2);
    createFooting(2.2);

    // Four adjustable telescoping struts
    const strutData = [];

    function createStrut(x, z, topX) {
      const bottom = new THREE.Vector3(x, 0.72, z);
      const top = new THREE.Vector3(topX, railHeight - 0.22, z);
      const length = top.distanceTo(bottom);
      const direction = top.clone().sub(bottom).normalize();

      const outerTop = bottom.clone().addScaledVector(direction, length * 0.59);
      const innerBottom = bottom.clone().addScaledVector(direction, length * 0.48);
      const collarBottom = bottom.clone().addScaledVector(direction, length * 0.52);
      const collarTop = bottom.clone().addScaledVector(direction, length * 0.62);

      cylinderBetween(
        supportGroup,
        bottom,
        outerTop,
        0.067,
        materials.darkSteel,
        20
      );

      cylinderBetween(
        supportGroup,
        innerBottom,
        top,
        0.046,
        materials.steel,
        18
      );

      cylinderBetween(
        supportGroup,
        collarBottom,
        collarTop,
        0.088,
        materials.brightSteel,
        20
      );

      const nut = new THREE.Mesh(
        new THREE.CylinderGeometry(0.115, 0.115, 0.19, 6),
        materials.darkSteel
      );
      nut.position.copy(
        bottom.clone().addScaledVector(direction, length * 0.53)
      );
      nut.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction
      );
      nut.castShadow = true;
      supportGroup.add(nut);

      // Small adjustment slot on the collar
      const slot = addBox(
        supportGroup,
        new THREE.Vector3(0.14, 0.025, 0.035),
        collarTop.clone().addScaledVector(direction, 0.015).add(
          new THREE.Vector3(0, 0, 0.082)
        ),
        materials.black,
        false
      );
      slot.rotation.z = -0.25;

      // Top mounting shoe
      addBox(
        supportGroup,
        new THREE.Vector3(0.27, 0.12, 0.27),
        new THREE.Vector3(topX, top.y + 0.07, z),
        materials.darkSteel
      );

      strutData.push({ bottom, top, length, direction });
    }

    for (const x of [-2.35, 2.35]) {
      createStrut(x, -0.8, -2.15);
      createStrut(x, 0.8, 2.15);
    }

    // Photovoltaic module
    addBox(
      moduleGroup,
      new THREE.Vector3(4.7, 2.7, 0.16),
      new THREE.Vector3(0, 0, 0),
      materials.black
    );

    const panel = new THREE.Mesh(
      new THREE.PlaneGeometry(4.46, 2.46),
      materials.panel
    );
    panel.position.z = 0.091;
    panel.receiveShadow = true;
    moduleGroup.add(panel);

    // Thin silver perimeter frame
    addBox(
      moduleGroup,
      new THREE.Vector3(4.72, 0.12, 0.13),
      new THREE.Vector3(0, 1.34, 0.125),
      materials.brightSteel
    );
    addBox(
      moduleGroup,
      new THREE.Vector3(4.72, 0.12, 0.13),
      new THREE.Vector3(0, -1.34, 0.125),
      materials.brightSteel
    );
    addBox(
      moduleGroup,
      new THREE.Vector3(0.12, 2.68, 0.13),
      new THREE.Vector3(-2.31, 0, 0.125),
      materials.brightSteel
    );
    addBox(
      moduleGroup,
      new THREE.Vector3(0.12, 2.68, 0.13),
      new THREE.Vector3(2.31, 0, 0.125),
      materials.brightSteel
    );

    // Small front identifier
    addBox(
      moduleGroup,
      new THREE.Vector3(0.92, 0.22, 0.025),
      new THREE.Vector3(-1.7, 0.86, 0.155),
      new THREE.MeshStandardMaterial({
        color: 0xd9e0dd,
        roughness: 0.8
      }),
      false
    );

    // Junction box on the rear of the module
    const junctionBox = new THREE.Group();
    junctionBox.position.set(0, 0.24, -0.23);
    moduleGroup.add(junctionBox);

    addBox(
      junctionBox,
      new THREE.Vector3(0.68, 0.48, 0.22),
      new THREE.Vector3(0, 0, 0),
      materials.black
    );

    addBox(
      junctionBox,
      new THREE.Vector3(0.62, 0.42, 0.035),
      new THREE.Vector3(0, 0, -0.13),
      materials.darkSteel
    );

    for (const x of [-0.2, 0.2]) {
      for (const y of [-0.13, 0.13]) {
        const screw = new THREE.Mesh(
          new THREE.CylinderGeometry(0.035, 0.035, 0.025, 12),
          materials.brightSteel
        );
        screw.rotation.x = Math.PI / 2;
        screw.position.set(x, y, -0.157);
        junctionBox.add(screw);
      }
    }

    // Rear service cable
    const cableCurve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(0.24, 0.34, -0.39),
      new THREE.Vector3(0.42, -0.2, -0.43),
      new THREE.Vector3(0.46, -0.85, -0.39),
      new THREE.Vector3(0.34, -1.24, -0.24)
    ]);

    const cable = new THREE.Mesh(
      new THREE.TubeGeometry(cableCurve, 28, 0.035, 10, false),
      materials.black
    );
    cable.castShadow = true;
    moduleGroup.add(cable);

    // Mounting clamps between the module and support crossbars
    for (const x of [-2.1, 2.1]) {
      for (const z of [-0.8, 0.8]) {
        addBox(
          moduleGroup,
          new THREE.Vector3(0.42, 0.16, 0.34),
          new THREE.Vector3(x, -1.47, z),
          materials.darkSteel
        );

        for (const dx of [-0.14, 0.14]) {
          const bolt = new THREE.Mesh(
            new THREE.CylinderGeometry(0.035, 0.035, 0.08, 12),
            materials.brightSteel
          );
          bolt.rotation.x = Math.PI / 2;
          bolt.position.set(x + dx, -1.47, z + 0.2);
          moduleGroup.add(bolt);
        }
      }
    }

    // UI state
    let tiltDegrees = 28;
    let railHeightValue = 2.55;

    function setRangeFill(input) {
      const min = Number(input.min);
      const max = Number(input.max);
      const value = Number(input.value);
      input.style.setProperty("--fill", `${((value - min) / (max - min)) * 100}%`);
    }

    function updateMechanism() {
      const degrees = tiltDegrees;
      moduleGroup.rotation.x = THREE.MathUtils.degToRad(degrees);
      moduleGroup.position.y = moduleCenterHeight + (railHeightValue - 2.55);

      const railY = railHeightValue;
      const crossbarY = railY - 0.15;

      for (const railZ of [-0.8, 0.8]) {
        supportGroup.children.forEach((object) => {
          if (object.isMesh && object.position) {
            if (
              object.geometry.parameters?.width === 5.45 &&
              object.position.y === railY
            ) {
              object.position.y = railY;
            }
            if (
              object.geometry.parameters?.width === 0.19 &&
              object.geometry.parameters?.depth === 1.86 &&
              object.position.y === crossbarY
            ) {
              object.position.y = crossbarY;
            }
          }
        });
      }

      for (const strut of strutData) {
        const bottom = strut.bottom;
        const top = strut.top;
        const length = strut.length;
        const direction = strut.direction;

        const outerTop = bottom.clone().addScaledVector(direction, length * 0.59);
        const innerBottom = bottom.clone().addScaledVector(direction, length * 0.48);
        const collarBottom = bottom.clone().addScaledVector(direction, length * 0.52);
        const collarTop = bottom.clone().addScaledVector(direction, length * 0.62);

        cylinderBetween(
          supportGroup,
          bottom,
          outerTop,
          0.067,
          materials.darkSteel,
          20
        );

        cylinderBetween(
          supportGroup,
          innerBottom,
          top,
          0.046,
          materials.steel,
          18
        );

        cylinderBetween(
          supportGroup,
          collarBottom,
          collarTop,
          0.088,
          materials.brightSteel,
          20
        );
      }

      tiltOutput.textContent = `${degrees}°`;
      heightOutput.textContent = `${railHeightValue.toFixed(2)} m`;
      tiltValue.textContent = `${degrees}°`;
      heightValue.textContent = `${railHeightValue.toFixed(2)} m`;

      setRangeFill(tiltInput);
      setRangeFill(heightInput);
    }

    // Custom orbit, pan, and zoom controls
    const pointers = new Map();
    let previousPinchDistance = 0;

    function pointerDistance() {
      const values = [...pointers.values()];
      if (values.length < 2) return 0;
      return Math.hypot(
        values[0].x - values[1].x,
        values[0].y - values[1].y
      );
    }

    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    canvas.addEventListener("pointerdown", (event) => {
      canvas.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 2) {
        previousPinchDistance = pointerDistance();
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      const previous = pointers.get(event.pointerId);
      if (!previous) return;

      const dx = event.clientX - previous.x;
      const dy = event.clientY - previous.y;
      pointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (pointers.size === 1) {
        const panning = event.shiftKey || event.buttons === 2;

        if (panning) {
          camera.updateMatrixWorld();
          const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
          const up = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 1);
          const panScale = controls.radius * 0.0014;

          controls.target
            .addScaledVector(right, -dx * panScale)
            .addScaledVector(up, dy * panScale);
        } else {
          controls.theta -= dx * 0.006;
          controls.phi -= dy * 0.006;
          controls.phi = THREE.MathUtils.clamp(controls.phi, 0.22, 1.48);
        }
      } else if (pointers.size === 2) {
        const distance = pointerDistance();
        if (previousPinchDistance > 0 && distance > 0) {
          controls.radius *= previousPinchDistance / distance;
          controls.radius = THREE.MathUtils.clamp(controls.radius, 5.2, 18);
        }
        previousPinchDistance = distance;
      }
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);
      previousPinchDistance = pointers.size === 2 ? pointerDistance() : 0;
    }

    canvas.addEventListener("pointerup", releasePointer);
    canvas.addEventListener("pointercancel", releasePointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        controls.radius *= Math.exp(event.deltaY * 0.001);
        controls.radius = THREE.MathUtils.clamp(controls.radius, 5.2, 18);
      },
      { passive: false }
    );

    function resetView() {
      controls.target.copy(defaultCamera.target);
      controls.radius = defaultCamera.radius;
      controls.theta = defaultCamera.theta;
      controls.phi = defaultCamera.phi;
    }

    document.querySelector("#reset").addEventListener("click", resetView);

    document.querySelector("#front").addEventListener("click", () => {
      controls.target.set(0, 2.55, 0);
      controls.radius = 9.6;
      controls.theta = 0;
      controls.phi = Math.PI / 2;
    });

    window.addEventListener("keydown", (event) => {
      if (
        event.target instanceof HTMLInputElement ||
        event.target instanceof HTMLButtonElement
      ) {
        return;
      }

      const key = event.key.toLowerCase();

      if (key === "arrowleft") controls.theta += 0.08;
      else if (key === "arrowright") controls.theta -= 0.08;
      else if (key === "arrowup") {
        controls.phi = Math.max(0.22, controls.phi - 0.06);
      } else if (key === "arrowdown") {
        controls.phi = Math.min(1.48, controls.phi + 0.06);
      } else if (key === "+" || key === "=") {
        controls.radius = Math.max(5.2, controls.radius * 0.9);
      } else if (key === "-" || key === "_") {
        controls.radius = Math.min(18, controls.radius * 1.1);
      } else if (key === "r") {
        resetView();
      } else {
        return;
      }

      event.preventDefault();
    });

    // Input handlers
    tiltInput.addEventListener("input", () => {
      tiltDegrees = Number(tiltInput.value);
      updateMechanism();
    });

    heightInput.addEventListener("input", () => {
      railHeightValue = Number(heightInput.value);
      updateMechanism();
    });

    setRangeFill(tiltInput);
    setRangeFill(heightInput);
    updateMechanism();

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    function animate() {
      requestAnimationFrame(animate);
      updateCamera();
      renderer.render(scene, camera);
    }

    animate();
    requestAnimationFrame(() => loading.classList.add("hidden"));
  </script>
